/* EducaConecta — protótipo navegável e demonstrativo, sem dados reais. */
const A=document.getElementById('app');
const state={page:'home',role:localStorage.getItem('ec_role')||'',tab:'overview',grade:'5º ano',subject:'Todos',search:'',question:0,answers:{},result:null,teacherSkill:'Frações',school:'Todas',ab:'disciplinas'};
const skills=[{name:'Frações',value:42,topic:'Frações e números decimais',recommend:'Trilha Frações no Cotidiano',students:16},{name:'Geometria',value:58,topic:'Figuras geométricas e propriedades',recommend:'Oficina Formas e Espaço',students:12},{name:'Operações',value:76,topic:'Resolução de problemas',recommend:'Desafios das Quatro Operações',students:6},{name:'Grandezas',value:85,topic:'Medidas e conversões',recommend:'Laboratório de Medidas',students:3}];
const resources=[{title:'Frações no cotidiano',subject:'Matemática',grade:'5º ano',type:'Trilha interativa',bncc:'EF05MA03',emoji:'🍰',desc:'Representação, leitura e comparação de números racionais na forma fracionária.'},{title:'Produção de textos narrativos',subject:'Língua Portuguesa',grade:'5º ano',type:'Plano de aula',bncc:'EF35LP25',emoji:'✏️',desc:'Construção de narrativas com sequência de acontecimentos e personagens.'},{title:'Desafios das operações',subject:'Matemática',grade:'5º ano',type:'Atividade',bncc:'EF05MA07',emoji:'➗',desc:'Situações-problema envolvendo adição e subtração com números naturais e decimais.'},{title:'Leitura e interpretação',subject:'Língua Portuguesa',grade:'6º ano',type:'Trilha interativa',bncc:'EF67LP28',emoji:'📚',desc:'Leitura autônoma e compreensão de textos literários.'},{title:'Geometria no nosso bairro',subject:'Matemática',grade:'6º ano',type:'Plano de aula',bncc:'EF06MA18',emoji:'📐',desc:'Análise de figuras geométricas em situações do cotidiano.'},{title:'Cartas de opinião',subject:'Língua Portuguesa',grade:'6º ano',type:'Atividade',bncc:'EF67LP05',emoji:'💬',desc:'Identificação e avaliação de opiniões e argumentos.'},{title:'Medidas e estimativas',subject:'Matemática',grade:'5º ano',type:'Atividade',bncc:'EF05MA19',emoji:'📏',desc:'Problemas de medidas de comprimento, área, massa e tempo.'},{title:'Leitura de gráficos',subject:'Matemática',grade:'5º ano',type:'Plano de aula',bncc:'EF05MA24',emoji:'📊',desc:'Interpretação de dados apresentados em tabelas e gráficos.'},{title:'Histórias de nossa comunidade',subject:'Língua Portuguesa',grade:'5º ano',type:'Plano de aula',bncc:'EF35LP26',emoji:'🏘️',desc:'Produção e compreensão de narrativas com diferentes linguagens.'},{title:'Números decimais',subject:'Matemática',grade:'6º ano',type:'Atividade',bncc:'EF06MA11',emoji:'🔢',desc:'Operações envolvendo números racionais decimais.'},{title:'Gêneros jornalísticos',subject:'Língua Portuguesa',grade:'6º ano',type:'Plano de aula',bncc:'EF67LP03',emoji:'📰',desc:'Comparação de informações e abordagens em notícias.'},{title:'Pontuação e sentido',subject:'Língua Portuguesa',grade:'5º ano',type:'Atividade',bncc:'EF05LP04',emoji:'🖊️',desc:'Exploração de usos da pontuação em diferentes textos.'}];
const courses=[{title:'BNCC na prática: planejamento pedagógico',hours:'10h',emoji:'🧩',cat:'Planejamento',progress:65},{title:'Metodologias ativas no Ensino Fundamental',hours:'8h',emoji:'💡',cat:'Metodologias',progress:0},{title:'Educação inclusiva e adaptação de atividades',hours:'12h',emoji:'🤝',cat:'Inclusão',progress:35},{title:'Avaliação formativa e recomposição da aprendizagem',hours:'6h',emoji:'📋',cat:'Avaliação',progress:0},{title:'Cultura digital e BNCC Computação',hours:'10h',emoji:'💻',cat:'Tecnologia',progress:0}];
const questions=[{q:'Qual fração representa três partes de um todo dividido em quatro partes iguais?',options:['1/3','3/4','4/3','3/8'],correct:1,skill:'Frações'},{q:'Uma pizza foi dividida em oito fatias iguais. Ana comeu duas. Que fração representa a parte que Ana comeu?',options:['2/8','8/2','1/8','6/8'],correct:0,skill:'Frações'},{q:'Qual destas figuras tem quatro lados iguais e quatro ângulos retos?',options:['Triângulo','Círculo','Quadrado','Pentágono'],correct:2,skill:'Geometria'},{q:'Uma escola possui 125 livros e recebe mais 48. Quantos livros terá ao todo?',options:['163','173','183','153'],correct:1,skill:'Operações'},{q:'Um metro equivale a quantos centímetros?',options:['10','100','1.000','50'],correct:1,skill:'Grandezas'}];
function go(page,tab){state.page=page;state.tab=tab||'overview';window.scrollTo({top:0,behavior:'instant'});render();history.replaceState(null,'','#'+page+(tab?'/'+tab:''))}
function icon(s){return `<span aria-hidden="true">${s}</span>`}
function brand(){return `<a class="brand" href="#home" onclick="event.preventDefault();go('home')"><span class="mark"><span></span><span></span><span></span><span></span><span></span></span><span class="brandtext"><b>Educa<em>Conecta</em></b><small>Aprender hoje. Transformar amanhã.</small></span></a>`}
function header(){return `<header class="site-header"><div class="container topbar">${brand()}<nav class="nav" id="nav">${[['home','Início'],['about','Sobre'],['resources','Recursos BNCC'],['courses','Formação'],['news','Notícias'],['help','Ajuda']].map(([p,n])=>`<a href="#${p}" class="${state.page===p?'active':''}" onclick="event.preventDefault();go('${p}');document.getElementById('nav').classList.remove('open')">${n}</a>`).join('')}</nav><div class="header-actions"><button class="btn sm" onclick="go('${state.role?'dashboard':'login'}')">${state.role?'Meu ambiente':'Entrar'} ↗</button><button class="menu-button" aria-label="Abrir menu" onclick="document.getElementById('nav').classList.toggle('open')">☰</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="container footgrid"><div>${brand()}<small>Protótipo conceitual de ecossistema educacional — EaDTech.</small></div><div><small>© 2026 EducaConecta · Dados, contas e resultados fictícios.<br>Sem conexão com sistemas Adobe, MEC ou instituições de ensino.</small></div></div></footer>`}
function hero(){return `<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Educação básica em novas possibilidades</div><h1>Um ecossistema.<br>Toda a <span class="accent">comunidade escolar.</span></h1><p>Conteúdos e atividades alinhados à BNCC, formação continuada, avaliações diagnósticas e inteligência educacional para alunos, professores e gestores.</p><div class="hero-actions"><button class="btn" onclick="go('about')">Conheça a plataforma →</button><button class="btn secondary" onclick="go('resources')">▤ Recursos da BNCC</button></div><span class="muted" style="font-size:13px">Uma solução digital complementar ao ensino presencial.</span></div><div class="hero-art" role="img" aria-label="Representação visual de uma comunidade escolar com estudante, professora e gestor"><div class="hero-tag">${icon('📘')} Trilhas de aprendizagem</div><div class="hero-tag">${icon('📊')} Indicadores e relatórios</div><div class="hero-tag">${icon('🎓')} Formação continuada</div></div></div></section>`}
function roles(){return `<div class="container role-cards">${[['student','blue','📖','Alunos','Aprender e praticar','Trilhas, disciplinas, simulados, atividades e recursos para desenvolver habilidades.'],['teacher','purple','🎓','Professores','Ensinar e desenvolver','Planos de aula, formação, diagnósticos e intervenções pedagógicas.'],['manager','green','📊','Gestores','Acompanhar e decidir','Indicadores, relatórios e visão da aprendizagem em toda a rede.']].map(([r,c,e,t,sub,desc])=>`<article class="role-card ${c}" onclick="selectRole('${r}');go('dashboard')"><div class="round">${e}</div><h3>${t}</h3><b style="color:#5b748f">${sub}</b><p>${desc}</p><span class="link">Explorar ambiente →</span></article>`).join('')}</div>`}
function home(){return `${hero()}${roles()}<section class="section"><div class="container"><div class="section-head"><div class="eyebrow">EducaConecta</div><h2>Uma plataforma para todo o ciclo pedagógico</h2><p>Aprender, avaliar e evoluir: do planejamento docente à recomposição da aprendizagem.</p></div><div class="feature-grid">${features()}</div></div></section><section class="section tinted"><div class="container"><div class="section-head"><div class="eyebrow">Avaliação e recomposição</div><h2>Identificar dificuldades. Transformar resultados em ação.</h2><p>Simulados e diagnósticos orientam atividades de reforço e oferecem aos professores uma visão clara das habilidades que merecem atenção.</p></div>${flow()}<div style="margin-top:24px"><button class="btn" onclick="selectRole('teacher');go('dashboard','diagnostics')">Ver painel de diagnóstico →</button></div></div></section><section class="section"><div class="container"><div class="cta"><div><h2>Conheça o EducaConecta por dentro</h2><p>Explore as três experiências com dados demonstrativos, sem precisar criar uma conta.</p></div><button class="btn" onclick="go('login')">Acessar demonstração →</button></div></div></section>`}
function features(){return [['📚','Aprendizagem','Trilhas, conteúdos e atividades para complementar o ensino presencial.'],['🎓','Formação docente','Cursos e recursos para o desenvolvimento profissional dos educadores.'],['📝','Avaliação e recomposição','Diagnósticos, simulados e planos de intervenção por habilidade.'],['📈','Inteligência educacional','Painéis e indicadores que apoiam decisões pedagógicas.'],['🧩','Recursos BNCC','Planos de aula e objetos educacionais classificados por habilidade.'],['✨','Jornadas personalizadas','Experiências relevantes para cada perfil da comunidade escolar.']].map(([e,t,d])=>`<article class="card"><div class="icon">${e}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}
function flow(){return `<div class="flow-steps">${[['01','Diagnóstico'],['02','Análise dos resultados'],['03','Pontos de atenção'],['04','Reforço pedagógico'],['05','Reavaliação']].map(([n,t])=>`<div class="flow-step"><b>${n}</b>${t}</div>`).join('')}</div>`}
function pageHeader(k,t,d){return `<section class="page-title"><div class="container"><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div></section>`}
function about(){return `${pageHeader('Sobre a plataforma','Educação conectada à realidade de cada rede','Uma solução educacional com marca própria, adaptável a redes municipais, estaduais e escolas particulares.') }<section class="section"><div class="container"><div class="feature-grid">${features()}</div><div class="section-head" style="margin-top:55px"><h2>Uma experiência integrada</h2><p>O professor atribui uma atividade, o aluno responde, o sistema apresenta indicadores de aprendizagem e o gestor visualiza os resultados consolidados.</p></div>${flow()}</div></section>`}
function resourceCards(){let matches=resources.filter(r=>(state.grade==='Todos'||r.grade===state.grade)&&(state.subject==='Todos'||r.subject===state.subject)&&(`${r.title} ${r.desc} ${r.bncc}`.toLowerCase().includes(state.search.toLowerCase())));return `<div class="feature-grid">${matches.map(r=>`<article class="card"><div class="icon">${r.emoji}</div><span class="label">${r.grade}</span> <span class="label green">${r.bncc}</span><h3 style="margin-top:15px">${r.title}</h3><p>${r.desc}</p><div class="card-bottom"><span class="muted">${r.subject} · ${r.type}</span><a class="link" href="#resource" onclick="event.preventDefault();showResource('${r.bncc}')">Ver recurso →</a></div></article>`).join('')}</div>${matches.length?'':`<div class="empty">Nenhum recurso encontrado. Experimente outros filtros.</div>`}`}
function resourcesPage(){return `${pageHeader('Biblioteca de recursos','Recursos educacionais alinhados à BNCC','Explore materiais, planos de aula e atividades classificados por etapa, componente curricular e habilidade.') }<section class="section"><div class="container"><div class="filters"><input aria-label="Buscar recursos" placeholder="Buscar por tema, título ou código BNCC" value="${state.search}" oninput="state.search=this.value;document.getElementById('resource-results').innerHTML=resourceCards()"><select aria-label="Filtrar por ano" onchange="state.grade=this.value;document.getElementById('resource-results').innerHTML=resourceCards()">${['Todos','5º ano','6º ano'].map(v=>`<option ${state.grade===v?'selected':''}>${v}</option>`).join('')}</select><select aria-label="Filtrar por disciplina" onchange="state.subject=this.value;document.getElementById('resource-results').innerHTML=resourceCards()">${['Todos','Matemática','Língua Portuguesa'].map(v=>`<option ${state.subject===v?'selected':''}>${v}</option>`).join('')}</select></div><div id="resource-results">${resourceCards()}</div><p class="small-note" style="margin-top:20px">Materiais ilustrativos para prototipagem. Antes da publicação efetiva, validar a correspondência entre cada descrição, o código BNCC e a matriz curricular adotada.</p></div></section>`}
function coursesPage(){return `${pageHeader('Desenvolvimento profissional','Formação continuada para educadores','Trilhas formativas, cursos e materiais para apoiar a prática pedagógica.') }<section class="section"><div class="container"><div class="course-grid">${courses.map((c,i)=>`<article class="card"><div class="icon">${c.emoji}</div><span class="label purple">${c.cat}</span><h3 style="margin-top:14px">${c.title}</h3><p>Curso demonstrativo · ${c.hours} · certificado de conclusão previsto</p><div class="card-bottom"><span class="muted">${c.hours}</span><button class="btn sm" onclick="selectRole('teacher');go('dashboard','training')">Conhecer curso →</button></div></article>`).join('')}</div></div></section>`}
function simplePage(type){const news=type==='news';return `${pageHeader(news?'Comunidade escolar':'Central de ajuda',news?'Notícias e novidades':'Como podemos ajudar?',news?'Atualizações, iniciativas e informações para educadores, alunos e gestores.':'Saiba como explorar os ambientes e testar os recursos demonstrativos do EducaConecta.') }<section class="section"><div class="container"><div class="feature-grid">${(news?[['📢','EducaConecta amplia recursos de avaliação','Conheça o novo ciclo de diagnóstico, reforço e reavaliação.'],['📘','Biblioteca BNCC em destaque','Filtre conteúdos por ano, disciplina e habilidade.'],['🎓','Formação para professores','Cursos para apoiar a prática docente e o planejamento.']]:[['🔐','Como acessar?','Clique em Entrar e selecione um dos três perfis demonstrativos.'],['📋','Como testar um simulado?','No ambiente do aluno, abra Simulado Diagnóstico e responda às cinco questões.'],['📊','Como visualizar os resultados?','No ambiente do professor, abra Pontos de atenção; no do gestor, abra Indicadores.']]).map(([e,t,d])=>`<article class="card"><div class="icon">${e}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>`}
function login(){return `<section class="login-wrap"><div class="login-panel"><div class="eyebrow" style="text-align:center">Acesso demonstrativo</div><h2>Qual ambiente deseja explorar?</h2><p style="text-align:center">Escolha um perfil. Não é necessário fornecer dados pessoais.</p><div class="persona-grid">${[['student','🧑‍🎓','Aluno','Estudar e realizar atividades'],['teacher','👩‍🏫','Professor','Planejar, avaliar e intervir'],['manager','👨‍💼','Gestor','Acompanhar indicadores']].map(([r,e,t,d])=>`<button class="persona ${state.role===r?'selected':''}" onclick="selectRole('${r}');render()"><div class="big">${e}</div><b>${t}</b><span class="muted">${d}</span></button>`).join('')}</div><div style="text-align:center"><button class="btn" onclick="selectRole(state.role||'student');go('dashboard')">Entrar na demonstração →</button></div><p class="login-note">Ambientes fictícios. Nenhum login, matrícula ou integração institucional é realizado.</p></div></section>`}
function selectRole(role){state.role=role;localStorage.setItem('ec_role',role);state.tab='overview'}
const menus={student:[['overview','🏠','Visão geral'],['subjects','📚','Minhas disciplinas'],['assessment','📝','Simulado diagnóstico'],['learning','🎯','Minha aprendizagem'],['activities','✅','Atividades']],teacher:[['overview','🏠','Visão geral'],['class','👥','Minha turma'],['diagnostics','📊','Pontos de atenção'],['planning','📖','Planos e recursos'],['training','🎓','Minha formação']],manager:[['overview','🏠','Visão geral'],['analytics','📊','Indicadores da rede'],['schools','🏫','Escolas e turmas'],['evaluations','📝','Avaliações externas'],['faculty','🎓','Formação docente']]};
function dashboard(){let role=state.role||'student';const roleTitle={student:'Aluno',teacher:'Professor',manager:'Gestor'}[role];return `<div class="dash-layout"><aside class="sidebar"><small>Ambiente do ${roleTitle}</small>${menus[role].map(([t,e,l])=>`<button class="side-link ${state.tab===t?'active':''}" onclick="go('dashboard','${t}')"><span class="side-ico">${e}</span>${l}</button>`).join('')}<small>Trocar ambiente</small><button class="side-link" onclick="go('login')"><span class="side-ico">↔</span>Alternar perfil</button><button class="side-link" onclick="logout()"><span class="side-ico">↩</span>Sair</button></aside><main class="dash-main"><div class="sim-banner">🧪 Ambiente demonstrativo: nomes, escolas, notas e indicadores são fictícios. As interações funcionam localmente no navegador.</div>${role==='student'?studentPanel():role==='teacher'?teacherPanel():managerPanel()}</main></div>`}
function intro(t,d,action=''){return `<div class="dash-intro"><div><h1>${t}</h1><p>${d}</p></div>${action}</div>`}
function stat(n,t){return `<div class="stat"><strong>${n}</strong><span>${t}</span></div>`}
function studentPanel(){if(state.tab==='assessment')return assessment();if(state.tab==='learning')return learning();if(state.tab==='subjects')return studentSubjects();if(state.tab==='activities')return studentActivities();return `${intro('Olá, Ana! 👋','Continue seu percurso de aprendizagem no EducaConecta.',`<button class="btn sm" onclick="go('dashboard','assessment')">Fazer simulado →</button>`)}<div class="stats">${stat('2','Disciplinas ativas')}${stat('60%','Trilha de Matemática')}${stat(state.result?state.result.score+' / 5':'—','Questões corretas no simulado')}${stat('4','Atividades da semana')}</div><div class="dashcols"><div><div class="panel"><h3>Continue aprendendo</h3>${listItem('🍰','Frações e números decimais','Matemática • 5º ano','Continuar',"go('dashboard','subjects')")}<div class="progress-track"><div class="progress-fill" style="width:60%"></div></div><p class="small-note">3 de 5 etapas concluídas</p>${listItem('📚','Leitura e interpretação','Língua Portuguesa • 5º ano','Abrir',"go('dashboard','subjects')")}</div><div class="panel"><h3>Avaliação diagnóstica</h3><p>Responda a cinco questões para conhecer suas habilidades e receber sugestões de estudo.</p><button class="btn" onclick="go('dashboard','assessment')">${state.result?'Refazer avaliação':'Começar avaliação'} →</button></div></div><div><div class="panel"><h3>Minha semana</h3>${[['Seg','Matemática: frações'],['Qua','Leitura e interpretação'],['Sex','Desafio de revisão']].map(([d,a])=>`<div class="list-row"><span class="tag">${d}</span><b>${a}</b></div>`).join('')}</div><div class="panel"><h3>Metas de estudo</h3><p>Concluir a trilha de frações e realizar o simulado diagnóstico.</p><div class="progress-track"><div class="progress-fill green" style="width:50%"></div></div></div></div></div>`}
function listItem(e,t,d,btn,onclick){return `<div class="list-row"><div class="row-start"><span class="circle">${e}</span><div><strong>${t}</strong><small>${d}</small></div></div><button class="btn ghost sm" onclick="${onclick}">${btn} →</button></div>`}
function studentSubjects(){return `${intro('Minhas disciplinas','Trilhas demonstrativas do Ensino Fundamental.') }<div class="course-grid">${[['➗','Matemática','Frações e números decimais','60%'],['📖','Língua Portuguesa','Leitura, interpretação e produção textual','35%']].map(([e,t,d,p])=>`<article class="card"><div class="icon">${e}</div><span class="label">5º ano</span><h3 style="margin-top:12px">${t}</h3><p>${d}</p><div class="progress-track" style="margin-top:20px"><div class="progress-fill" style="width:${p}"></div></div><small>${p} concluído</small><div class="card-bottom"><button class="btn sm" onclick="go('dashboard','activities')">Ver atividades →</button></div></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>Trilha de Matemática — Frações e números decimais</h3>${[['✓','Entendendo as frações','Vídeo introdutório'],['✓','Frações no cotidiano','Conteúdo interativo'],['✓','Desafio das frações','Exercícios resolvidos'],['○','Praticando operações','Atividade'],['○','Revisão do aprendizado','Avaliação']].map(([e,t,d])=>`<div class="list-row"><div class="row-start"><span class="circle">${e}</span><div><strong>${t}</strong><small>${d}</small></div></div><span class="tag">${e==='✓'?'Concluído':'A fazer'}</span></div>`).join('')}</div>`}
function studentActivities(){return `${intro('Minhas atividades','Exercícios de apoio e tarefas atribuídas pela professora.') }<div class="panel">${listItem('📝','Simulado diagnóstico de Matemática','5 questões · autocorreção','Realizar',"go('dashboard','assessment')")}${listItem('🍰','Prática: frações no cotidiano','5º ano · recomposição da aprendizagem','Acessar',"go('dashboard','subjects')")}${listItem('📚','Leitura guiada','Língua Portuguesa · interpretação','Acessar',"go('dashboard','subjects')")}</div>`}
function assessment(){if(state.result)return assessmentResult();let q=questions[state.question];return `${intro('Simulado diagnóstico','Matemática · 5º ano · 5 questões de demonstração')}<div class="panel" style="max-width:820px"><div style="display:flex;justify-content:space-between;align-items:center"><span class="label">Questão ${state.question+1} de ${questions.length}</span><span class="muted">Habilidade: ${q.skill}</span></div><div class="progress-track" style="margin:17px 0 24px"><div class="progress-fill" style="width:${((state.question+1)/questions.length)*100}%"></div></div><div class="assessment-question"><h3>${q.q}</h3><div class="answers">${q.options.map((o,i)=>`<button class="answer ${state.answers[state.question]===i?'chosen':''}" onclick="state.answers[${state.question}]=${i};render()"><b>${'ABCD'[i]}.</b> ${o}</button>`).join('')}</div></div><div style="display:flex;justify-content:space-between;gap:12px"><button class="btn secondary" ${state.question===0?'disabled':''} onclick="state.question=Math.max(0,state.question-1);render()">← Anterior</button><button class="btn" ${state.answers[state.question]===undefined?'disabled':''} onclick="nextQuestion()">${state.question===questions.length-1?'Finalizar avaliação':'Próxima questão →'}</button></div></div><p class="small-note">As questões são autorais e ilustrativas, não são itens oficiais do Saeb ou do Inep.</p>`}
function nextQuestion(){if(state.answers[state.question]===undefined)return;if(state.question<questions.length-1){state.question++;render()}else{let score=questions.reduce((s,q,i)=>s+(state.answers[i]===q.correct?1:0),0);state.result={score,date:new Date().toLocaleDateString('pt-BR')};state.question=0;go('dashboard','assessment');toast('Avaliação concluída! Veja seus resultados.') }}
function assessmentResult(){let score=state.result.score;return `${intro('Resultado da avaliação','Diagnóstico ilustrativo • Matemática • 5º ano')}<div class="stats">${stat(score+' / 5','Acertos')}${stat((score*20)+'%','Aproveitamento')}${stat('5','Questões respondidas')}${stat('1','Trilha recomendada')}</div><div class="panel"><h3>Devolutiva de aprendizagem</h3><p>${score>=4?'Excelente participação. Continue praticando para consolidar as habilidades.':'Você já concluiu o diagnóstico! Vamos revisar alguns conteúdos e praticar novamente.'}</p><div class="detail-banner"><b>📘 Recurso sugerido: Frações no cotidiano</b><p>Estude com exemplos do dia a dia, exercícios de comparação de frações e desafios de revisão.</p><button class="btn sm" onclick="go('dashboard','subjects')">Explorar trilha →</button></div><div style="margin-top:20px"><h3>Respostas</h3>${questions.map((q,i)=>`<div class="list-row"><div><b>${i+1}. ${q.skill}</b><small>${q.q}</small></div><span class="label ${state.answers[i]===q.correct?'green':'gold'}">${state.answers[i]===q.correct?'Correta':'Revisar'}</span></div>`).join('')}</div><button class="btn secondary" style="margin-top:15px" onclick="state.result=null;state.answers={};state.question=0;go('dashboard','assessment')">Refazer simulado</button></div>`}
function learning(){return `${intro('Minha aprendizagem','Acompanhe o que você já aprendeu e onde pode avançar.')}<div class="stats">${stat('60%','Matemática')}${stat('35%','Língua Portuguesa')}${stat(state.result?`${state.result.score*20}%`:'—','Último diagnóstico')}${stat('2','Trilhas em andamento')}</div><div class="panel"><h3>Minha evolução</h3><p>As informações abaixo ilustram a progressão individual de estudos.</p>${[['Matemática',60],['Língua Portuguesa',35],['Atividades de reforço',45]].map(([t,v])=>`<div style="margin:17px 0"><div style="display:flex;justify-content:space-between"><b>${t}</b><b>${v}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${v}%"></div></div></div>`).join('')}</div>`}
function teacherPanel(){if(state.tab==='diagnostics')return diagnostics();if(state.tab==='class')return teacherClass();if(state.tab==='planning')return planning();if(state.tab==='training')return training();return `${intro('Olá, professora Marina! 👋','Sua turma e seus recursos em um só lugar.',`<button class="btn sm" onclick="go('dashboard','diagnostics')">Ver diagnóstico →</button>`)}<div class="stats">${stat('28','Alunos na turma')}${stat('65%','Acerto médio ilustrativo')}${stat('2','Habilidades em atenção')}${stat('3','Cursos disponíveis')}</div><div class="dashcols"><div><div class="panel"><h3>Diagnóstico da turma · Matemática, 5º A</h3>${skillBars()}<button class="btn sm" style="margin-top:17px" onclick="go('dashboard','diagnostics')">Analisar pontos de atenção →</button></div></div><div><div class="panel"><h3>Próximas ações</h3><div class="timeline"><div class="step"><b>Revisar frações</b><p>16 alunos com necessidade de apoio.</p></div><div class="step"><b>Atribuir trilha de reforço</b><p>Frações no cotidiano.</p></div><div class="step"><b>Realizar reavaliação</b><p>Acompanhar evolução da turma.</p></div></div></div></div></div>`}
function skillBars(){return skills.map(s=>`<div style="margin:13px 0"><div style="display:flex;justify-content:space-between;gap:8px"><b>${s.name}</b><span>${s.value}% ${s.value<60?'<span class="label gold">Atenção</span>':''}</span></div><div class="progress-track"><div class="progress-fill ${s.value<60?'warn':'green'}" style="width:${s.value}%"></div></div></div>`).join('')}
function diagnostics(){let s=skills.find(s=>s.name===state.teacherSkill)||skills[0];return `${intro('Pontos de atenção da turma','Matemática · 5º ano A · Avaliação diagnóstica demonstrativa')}<div class="stats">${stat('28','Alunos avaliados')}${stat('65%','Média ilustrativa')}${stat('2','Habilidades em atenção')}${stat('4','Habilidades analisadas')}</div><div class="dashcols"><div><div class="panel"><h3>Desempenho por habilidade</h3>${skills.map(s=>`<button style="display:block;text-align:left;background:${state.teacherSkill===s.name?'#f0f7ff':'transparent'};border:0;border-radius:9px;padding:8px;width:100%;color:inherit" onclick="state.teacherSkill='${s.name}';render()"><div style="display:flex;justify-content:space-between"><b>${s.name}</b><span>${s.value}% ${s.value<60?'⚠️':''}</span></div><div class="progress-track"><div class="progress-fill ${s.value<60?'warn':'green'}" style="width:${s.value}%"></div></div></button>`).join('')}<p class="small-note" style="margin-top:12px">Clique em uma habilidade para consultar a orientação. Limite demonstrativo de 60%; não é uma faixa oficial de proficiência do Saeb.</p></div><div class="panel"><h3>Mapa de habilidades por turma</h3><div class="table-wrap"><table class="heatmap"><thead><tr><th>Turma</th>${skills.map(s=>`<th>${s.name}</th>`).join('')}</tr></thead><tbody>${[['5º A',42,58,76,85],['5º B',63,71,80,77],['5º C',55,69,74,83]].map(r=>`<tr><th>${r[0]}</th>${r.slice(1).map(v=>`<td class="${v<60?'heat-low':v<75?'heat-mid':'heat-high'}">${v}%</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></div><div><div class="panel"><h3>Orientação pedagógica</h3><span class="label ${s.value<60?'gold':'green'}">${s.value<60?'Ponto de atenção':'Em acompanhamento'}</span><h3 style="margin:16px 0 7px">${s.name}</h3><p>${s.topic}. ${s.value<60?'Recomenda-se retomar os conceitos e aplicar atividades de reforço antes de uma nova avaliação.':'Recomenda-se manter prática e acompanhar a consolidação da aprendizagem.'}</p><div class="detail-banner"><b>📘 Recurso recomendado</b><p>${s.recommend}</p><button class="btn sm" onclick="toast('Atividade de reforço atribuída à turma 5º A (simulação).')">Atribuir à turma →</button></div><div class="list-row"><span>Alunos que precisam de apoio*</span><b>${s.students}</b></div><button class="btn secondary sm" onclick="toast('Reavaliação agendada para a turma 5º A (simulação).')">Agendar reavaliação</button><p class="small-note" style="margin-top:14px">*Contagem fictícia para demonstrar agrupamento pedagógico. A identificação real requer regras de análise, dados suficientes e revisão docente.</p></div></div></div>`}
function teacherClass(){return `${intro('Minha turma','5º ano A · Escola Municipal Horizonte · Dados fictícios')}<div class="stats">${stat('28','Estudantes')}${stat('26','Ativos na plataforma')}${stat('24','Realizaram atividades')}${stat('65%','Média do diagnóstico')}</div><div class="panel"><h3>Atividades da turma</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Atividade</th><th>Área</th><th>Participação</th><th>Ação</th></tr></thead><tbody>${[['Simulado diagnóstico','Matemática','24/28'],['Leitura guiada','Português','22/28'],['Frações no cotidiano','Matemática','19/28']].map(([t,a,n])=>`<tr><td>${t}</td><td>${a}</td><td>${n}</td><td><button class="btn ghost sm" onclick="go('dashboard','diagnostics')">Ver resultados</button></td></tr>`).join('')}</tbody></table></div><p class="small-note">Participação refere-se ao acesso e conclusão de atividades online, não à frequência escolar presencial.</p></div>`}
function planning(){return `${intro('Planos e recursos','Biblioteca de atividades para suas aulas e intervenções pedagógicas.')}<div class="feature-grid">${resources.slice(0,6).map(r=>`<article class="card"><div class="icon">${r.emoji}</div><span class="label">${r.bncc}</span><h3 style="margin-top:14px">${r.title}</h3><p>${r.desc}</p><div class="card-bottom"><span>${r.grade}</span><button class="btn ghost sm" onclick="toast('Recurso salvo no planejamento (simulação).')">Salvar no plano +</button></div></article>`).join('')}</div>`}
function training(){return `${intro('Minha formação','Cursos e trilhas para o desenvolvimento profissional.')}<div class="course-grid">${courses.map(c=>`<article class="card"><div class="icon">${c.emoji}</div><span class="label purple">${c.cat}</span><h3 style="margin-top:14px">${c.title}</h3><p>Curso de ${c.hours} · demonstração</p><div class="progress-track" style="margin-top:18px"><div class="progress-fill" style="width:${c.progress}%"></div></div><small>${c.progress?`${c.progress}% concluído`:'Não iniciado'}</small><div class="card-bottom"><button class="btn sm" onclick="toast('Inscrição registrada na demonstração. A integração real com o ALM está pendente.')">${c.progress?'Continuar curso':'Inscrever-se'} →</button></div></article>`).join('')}</div>`}
function managerPanel(){if(state.tab==='analytics')return managerAnalytics();if(state.tab==='schools')return schools();if(state.tab==='evaluations')return evaluations();if(state.tab==='faculty')return managerFaculty();return `${intro('Visão geral da rede','Panorama demonstrativo da Rede Municipal Horizonte.',`<button class="btn sm" onclick="go('dashboard','analytics')">Explorar indicadores →</button>`)}<div class="stats">${stat('12','Unidades escolares')}${stat('4.280','Alunos cadastrados')}${stat('238','Professores')}${stat('76%','Participação nas atividades')}</div><div class="dashcols"><div><div class="panel"><h3>Participação nas atividades</h3><div class="mini-chart">${[40,55,48,68,64,75,84].map(n=>`<div class="bar" style="height:${n}%"></div>`).join('')}</div><div class="chart-labels">${['Abr','Mai','Jun','Jul','Ago','Set','Out'].map(m=>`<span>${m}</span>`).join('')}</div><p class="small-note">Série temporal inteiramente ilustrativa.</p></div><div class="panel"><h3>Habilidades em foco</h3>${skillBars()}</div></div><div><div class="panel"><h3>Distribuição de atividades</h3>${[['Matemática',82],['Língua Portuguesa',74],['Formação docente',61]].map(([t,v])=>`<div style="margin-bottom:14px"><div style="display:flex;justify-content:space-between"><b>${t}</b><span>${v}%</span></div><div class="progress-track"><div class="progress-fill green" style="width:${v}%"></div></div></div>`).join('')}</div><div class="panel"><h3>Acompanhamento pedagógico</h3><p>Explore o mapa de resultados por escola e consulte informações demonstrativas de habilidades que exigem apoio.</p><button class="btn secondary sm" onclick="go('dashboard','analytics')">Abrir painel →</button></div></div></div>`}
function managerAnalytics(){return `${intro('Inteligência educacional','Indicadores para apoiar decisões pedagógicas.') }<div class="filters"><label>Escola: <select onchange="state.school=this.value;render()">${['Todas','Escola Horizonte','Escola Jardim Azul','Escola Primavera'].map(n=>`<option ${state.school===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="stats">${stat(state.school==='Todas'?'12':'1','Escolas no filtro')}${stat(state.school==='Todas'?'4.280':'364','Alunos cadastrados')}${stat(state.school==='Todas'?'76%':'81%','Participação')}${stat(state.school==='Todas'?'65%':'69%','Acerto médio ilustrativo')}</div><div class="dashcols"><div class="panel"><h3>Resultados por habilidades</h3>${skillBars()}<p class="small-note">Não se trata de nota Saeb nem de índice Ideb oficial.</p></div><div class="panel"><h3>Evolução de participação</h3><div class="mini-chart">${[35,48,46,61,72,69,83].map(n=>`<div class="bar" style="height:${n}%"></div>`).join('')}</div><div class="chart-labels">${['Abr','Mai','Jun','Jul','Ago','Set','Out'].map(m=>`<span>${m}</span>`).join('')}</div></div></div><div class="panel"><h3>Mapa de intervenção recomendado</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Escola</th><th>Habilidade em atenção</th><th>Acerto ilustrativo</th><th>Ação sugerida</th></tr></thead><tbody>${[['Escola Horizonte','Frações','42%','Trilha de reforço'],['Escola Jardim Azul','Geometria','55%','Oficina prática'],['Escola Primavera','Leitura','59%','Leitura guiada']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function schools(){return `${intro('Escolas e turmas','Comparativo ilustrativo de participação e desempenho.')}<div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Escola</th><th>Alunos</th><th>Participação</th><th>Indicador diagnóstico*</th></tr></thead><tbody>${[['Escola Municipal Horizonte','364','81%','69%'],['Escola Jardim Azul','428','73%','62%'],['Escola Primavera','396','78%','67%'],['Escola Vale Verde','451','71%','64%']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small-note">*Médias fictícias de exercícios da plataforma, não indicadores oficiais da rede ou do MEC.</p></div>`}
function evaluations(){return `${intro('Avaliações externas e diagnósticos','Acompanhamento orientado à aprendizagem e às matrizes de referência.')}<div class="panel"><h3>Jornada de avaliação e recomposição</h3>${flow()}<p style="margin-top:17px">O EducaConecta pode organizar simulados e diagnósticos alinhados a matrizes de referência, conectar os resultados a conteúdos de reforço e apoiar o trabalho docente.</p></div><div class="feature-grid">${[['📘','Saeb','Referências para alfabetização e anos escolares avaliados pelo Inep, conforme edição e matriz.'],['🎯','Enem','Percursos e simulados para o Ensino Médio, previstos para futura expansão.'],['📋','Encceja','Trilhas de preparação para jovens e adultos, previstas para futura expansão.'],['🧭','Avaliações formativas','Diagnósticos periódicos por habilidades, com intervenções e reavaliação.'],['📊','Ideb','Exibição de indicadores oficiais de referência quando houver integração com fonte validada.']].map(([e,t,d])=>`<article class="card"><div class="icon">${e}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>Conceito importante</h3><p>BNCC, matrizes de referência e questões avaliativas exigem mapeamento pedagógico próprio. O protótipo não possui banco oficial de questões do Inep nem calcula proficiência Saeb ou Ideb.</p></div>`}
function managerFaculty(){return `${intro('Formação docente na rede','Cursos, conclusão e adesão dos educadores.')}<div class="stats">${stat('238','Professores cadastrados')}${stat('172','Inscrições em cursos')}${stat('84','Conclusões demonstrativas')}${stat('49%','Taxa ilustrativa de conclusão')}</div><div class="panel"><h3>Formações mais acessadas</h3>${courses.slice(0,4).map((c,i)=>`<div class="list-row"><div class="row-start"><span class="circle">${c.emoji}</span><div><b>${c.title}</b><small>${c.hours}</small></div></div><span class="tag">${[73,57,41,32][i]} inscrições</span></div>`).join('')}</div>`}
function logout(){state.role='';localStorage.removeItem('ec_role');go('home');toast('Você saiu do ambiente demonstrativo.')}
function showResource(code){let r=resources.find(r=>r.bncc===code);if(!r)return;toast(`${r.title}: recurso ilustrativo do catálogo BNCC.`)}
function toast(s){let e=document.getElementById('toast');e.textContent=s;e.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('visible'),3300)}
function render(){A.innerHTML=header()+({home,about,resources:resourcesPage,courses:coursesPage,news:()=>simplePage('news'),help:()=>simplePage('help'),login,dashboard}[state.page]||home)()+footer();document.title='EducaConecta | '+(state.page==='home'?'Aprender hoje. Transformar amanhã.':state.page==='dashboard'?'Ambiente demonstrativo':'Portal Educacional')}

/* ================= V2 | Avaliação e Recomposição ================= */
const v2key='educaconecta_v2_demo';
function defaultCycle(){return {diagnostic:null,reinforcement:null,practice:null,reassessment:null,events:[]}}
let cycle;
try {cycle={...defaultCycle(),...JSON.parse(localStorage.getItem(v2key)||'{}')}}catch(e){cycle=defaultCycle()}
function saveCycle(){localStorage.setItem(v2key,JSON.stringify(cycle))}
function cycleEvent(label){cycle.events.unshift({label,date:new Date().toLocaleString('pt-BR')});cycle.events=cycle.events.slice(0,12);saveCycle()}
const v2Q={
  diagnostic:[
    {q:'Qual fração corresponde a 3 partes de 4 partes iguais?',options:['1/4','3/4','4/3','3/8'],correct:1,skill:'Frações'},
    {q:'João dividiu uma barra em 8 partes e comeu 2. Qual fração comeu?',options:['2/8','8/2','1/8','6/8'],correct:0,skill:'Frações'},
    {q:'Qual figura possui quatro lados iguais e quatro ângulos retos?',options:['Triângulo','Losango qualquer','Quadrado','Trapézio'],correct:2,skill:'Geometria'},
    {q:'125 + 48 é igual a:',options:['163','173','183','153'],correct:1,skill:'Operações'},
    {q:'Um metro corresponde a quantos centímetros?',options:['10','100','1.000','50'],correct:1,skill:'Grandezas'}],
  practice:[
    {q:'Qual fração equivale à metade?',options:['1/3','2/4','3/4','1/5'],correct:1,skill:'Frações'},
    {q:'Em um total de 10 lápis, 3 são vermelhos. Que fração é vermelha?',options:['3/10','10/3','7/10','1/3'],correct:0,skill:'Frações'},
    {q:'Qual fração é maior?',options:['1/4','3/4','1/8','2/8'],correct:1,skill:'Frações'}],
  reassessment:[
    {q:'Se uma pizza de 8 fatias teve 4 consumidas, qual fração foi consumida?',options:['2/8','4/8','8/4','1/8'],correct:1,skill:'Frações'},
    {q:'Qual número representa três quartos?',options:['3/4','4/3','3/8','1/4'],correct:0,skill:'Frações'},
    {q:'Uma fita tem 100 centímetros. Quantos metros ela tem?',options:['10','100','1','0,1'],correct:2,skill:'Grandezas'},
    {q:'Uma caixa tem 24 lápis. Depois de distribuir 8, quantos restam?',options:['12','14','16','18'],correct:2,skill:'Operações'},
    {q:'Qual sólido geométrico possui seis faces quadradas?',options:['Cone','Esfera','Cubo','Cilindro'],correct:2,skill:'Geometria'}]
};
let v2quiz={type:'diagnostic',pos:0,answers:{}};
function startV2Quiz(type){v2quiz={type,pos:0,answers:{}};go('dashboard','cycle-quiz')}
function quizTypeLabel(type){return {diagnostic:'Diagnóstico inicial',practice:'Atividade de reforço',reassessment:'Reavaliação'}[type]}
function finishV2Quiz(){const qs=v2Q[v2quiz.type];if(Object.keys(v2quiz.answers).length!==qs.length)return;const score=qs.filter((q,i)=>q.correct===v2quiz.answers[i]).length;let result={score,total:qs.length,percent:Math.round(score/qs.length*100),bySkill:{},date:new Date().toLocaleDateString('pt-BR')};qs.forEach((q,i)=>{let x=result.bySkill[q.skill]||{correct:0,total:0};x.total++;x.correct+=Number(q.correct===v2quiz.answers[i]);result.bySkill[q.skill]=x});cycle[v2quiz.type]=result;cycleEvent(`${quizTypeLabel(v2quiz.type)} concluída: ${result.percent}%`);go('dashboard','cycle-results')}
function scoreCards(){return `<div class="stats">${stat(cycle.diagnostic?cycle.diagnostic.percent+'%':'—','Diagnóstico')}${stat(cycle.reinforcement?'Atribuído':'Pendente','Plano de reforço')}${stat(cycle.practice?cycle.practice.percent+'%':'—','Atividade de reforço')}${stat(cycle.reassessment?cycle.reassessment.percent+'%':'—','Reavaliação')}</div>`}
function cycleTimeline(){let items=[['Diagnóstico inicial',!!cycle.diagnostic],['Análise das habilidades',!!cycle.diagnostic],['Atribuição de reforço',!!cycle.reinforcement],['Atividade de reforço',!!cycle.practice],['Reavaliação',!!cycle.reassessment]];return `<div class="cycle-steps">${items.map(([t,done],i)=>`<div class="cycle-step ${done?'done':''}"><span>${done?'✓':i+1}</span><b>${t}</b><small>${done?'Etapa registrada':'Aguardando'}</small></div>`).join('')}</div>`}
function cycleQuiz(){let qs=v2Q[v2quiz.type],q=qs[v2quiz.pos];return `${intro(quizTypeLabel(v2quiz.type),'Matemática · 5º ano · Questões autorais demonstrativas')}<div class="panel quiz-shell"><div class="q-meta"><span class="label">Questão ${v2quiz.pos+1} de ${qs.length}</span><span>Habilidade: ${q.skill}</span></div><div class="progress-track" style="margin:18px 0 25px"><div class="progress-fill" style="width:${100*(v2quiz.pos+1)/qs.length}%"></div></div><h2>${q.q}</h2><div class="answers">${q.options.map((op,i)=>`<button class="answer ${v2quiz.answers[v2quiz.pos]===i?'chosen':''}" onclick="v2quiz.answers[${v2quiz.pos}]=${i};render()"><b>${'ABCD'[i]}.</b> ${op}</button>`).join('')}</div><div class="quiz-actions"><button class="btn secondary" ${v2quiz.pos===0?'disabled':''} onclick="v2quiz.pos--;render()">← Anterior</button><button class="btn" ${v2quiz.answers[v2quiz.pos]===undefined?'disabled':''} onclick="${v2quiz.pos===qs.length-1?'finishV2Quiz()':'v2quiz.pos++;render()'}">${v2quiz.pos===qs.length-1?'Concluir':'Próxima →'}</button></div></div>`}
function resultPanel(){const r=cycle[v2quiz.type];if(!r)return cycleStudent();return `${intro('Resultado: '+quizTypeLabel(v2quiz.type),'Resposta registrada na demonstração local.')}<div class="stats">${stat(r.score+' / '+r.total,'Acertos')}${stat(r.percent+'%','Aproveitamento')}${stat(Object.keys(r.bySkill).length,'Habilidades observadas')}${stat(r.date,'Data da realização')}</div><div class="panel"><h3>Devolutiva por habilidade</h3>${Object.entries(r.bySkill).map(([s,z])=>`<div class="skill-line"><b>${s}</b><div class="progress-track"><div class="progress-fill ${z.correct/z.total<.6?'warn':'green'}" style="width:${100*z.correct/z.total}%"></div></div><b>${z.correct} / ${z.total}</b></div>`).join('')}<p class="small-note">Número de itens insuficiente para inferir proficiência. Os resultados servem exclusivamente à simulação de interface.</p>${v2quiz.type==='diagnostic'?`<div class="detail-banner"><b>Próximo passo: intervenção orientada</b><p>O professor poderá visualizar o resultado demonstrativo e atribuir uma atividade de recomposição.</p></div>`:v2quiz.type==='practice'?`<div class="detail-banner"><b>Atividade concluída</b><p>A reavaliação pode agora ser realizada para observar a evolução.</p></div>`:`<div class="detail-banner"><b>Evolução observada</b><p>Diagnóstico: ${cycle.diagnostic?.percent??'—'}% · Reavaliação: ${r.percent}%. Amostras pequenas não representam medidas oficiais de proficiência.</p></div>`}<button class="btn" onclick="go('dashboard','cycle')">Voltar ao ciclo →</button></div>`}
function cycleStudent(){return `${intro('Avaliação e recomposição','Sua jornada de diagnóstico, estudo e reavaliação em Matemática • 5º ano.')} ${scoreCards()}<div class="panel"><h3>Meu percurso</h3>${cycleTimeline()}</div><div class="cycle-grid"><div class="panel"><span class="label">ETAPA 1</span><h3>Diagnóstico</h3><p>Responda a cinco questões para identificar conteúdos que podem precisar de revisão.</p><button class="btn" onclick="startV2Quiz('diagnostic')">${cycle.diagnostic?'Refazer diagnóstico':'Iniciar diagnóstico'} →</button></div><div class="panel"><span class="label purple">ETAPA 2</span><h3>Reforço personalizado</h3><p>${cycle.reinforcement?'A professora atribuiu a trilha Frações no cotidiano. Você pode praticar agora.':'Aguarde a atribuição da atividade pelo professor após a análise do diagnóstico.'}</p><button class="btn" ${!cycle.reinforcement?'disabled':''} onclick="startV2Quiz('practice')">${cycle.practice?'Refazer prática':'Realizar atividade'} →</button></div><div class="panel"><span class="label green">ETAPA 3</span><h3>Reavaliação</h3><p>Depois de concluir o reforço, responda a novas questões e compare o resultado.</p><button class="btn" ${!cycle.practice?'disabled':''} onclick="startV2Quiz('reassessment')">${cycle.reassessment?'Refazer reavaliação':'Iniciar reavaliação'} →</button></div></div><div class="panel"><h3>Meu histórico de aprendizagem</h3>${cycle.events.length?cycle.events.map(e=>`<div class="list-row"><b>${e.label}</b><small>${e.date}</small></div>`).join(''):'<p>Nenhuma etapa concluída ainda.</p>'}</div>`}
function assignReinforcement(){cycle.reinforcement={title:'Frações no cotidiano',group:'5º ano A',date:new Date().toLocaleDateString('pt-BR')};cycleEvent('Professora atribuiu trilha de frações à turma');render();toast('Plano de reforço atribuído. Acesse como Aluno para realizar a atividade.')}
function cycleTeacher(){let d=cycle.diagnostic;return `${intro('Avaliação e recomposição','Diagnóstico por habilidade e intervenção pedagógica · Turma 5º A')} ${scoreCards()}<div class="panel"><h3>Ciclo pedagógico compartilhado</h3>${cycleTimeline()}</div><div class="cycle-grid"><div class="panel"><span class="label">DIAGNÓSTICO</span><h3>Resultado da atividade</h3><p>${d?'Uma estudante demonstrativa concluiu o diagnóstico com '+d.percent+'% de acertos.':'O diagnóstico da estudante demonstrativa ainda não foi respondido.'}</p><button class="btn secondary sm" onclick="selectRole('student');go('dashboard','cycle')">Ver como aluno →</button></div><div class="panel"><span class="label gold">INTERVENÇÃO</span><h3>Plano de recomposição</h3><p>Proposta: trilha Frações no cotidiano, exercícios e registro de acompanhamento.</p><button class="btn" ${!d?'disabled':''} onclick="assignReinforcement()">${cycle.reinforcement?'Reatribuir reforço':'Atribuir reforço'} →</button></div><div class="panel"><span class="label green">ACOMPANHAMENTO</span><h3>Reavaliação</h3><p>${cycle.reassessment?`Resultado ilustrativo: ${cycle.reassessment.percent}%. Compare com o diagnóstico e revise a estratégia de apoio.`:'A reavaliação ficará disponível ao aluno após concluir o reforço.'}</p><button class="btn secondary sm" onclick="go('dashboard','cycle-report')">Relatório de evolução →</button></div></div><div class="panel"><h3>Pontos de atenção por habilidade</h3><p>Mapa agregado e fictício da turma; abaixo, o registro individual concluído nesta demonstração.</p>${skillBars()}${d?`<h3 style="margin-top:26px">Resultado individual demonstrativo</h3>${Object.entries(d.bySkill).map(([s,v])=>`<div class="skill-line"><b>${s}</b><div class="progress-track"><div class="progress-fill ${v.correct/v.total<.6?'warn':'green'}" style="width:${v.correct/v.total*100}%"></div></div><span>${v.correct}/${v.total}</span></div>`).join('')}`:''}<p class="small-note">O painel de turma é ilustrativo. Não agrega automaticamente os dados do único estudante demonstrativo às estatísticas da rede.</p></div>`}
function cycleReport(){return `${intro('Relatório de evolução','Comparação ilustrativa do ciclo de aprendizagem')} ${scoreCards()}<div class="panel"><h3>Antes e depois da intervenção</h3><div class="cycle-compare">${[['Diagnóstico inicial',cycle.diagnostic?.percent],['Reavaliação',cycle.reassessment?.percent]].map(([l,v])=>`<div class="compare-card"><span>${l}</span><strong>${v===undefined?'—':v+'%'}</strong><div class="progress-track"><div class="progress-fill" style="width:${v??0}%"></div></div></div>`).join('')}</div><p>${cycle.diagnostic&&cycle.reassessment?`Variação observada de ${cycle.reassessment.percent-cycle.diagnostic.percent>=0?'+':''}${cycle.reassessment.percent-cycle.diagnostic.percent} pontos percentuais em conjuntos demonstrativos diferentes de questões.`:'Conclua o diagnóstico, atribua o reforço, realize a prática e a reavaliação para visualizar os dois resultados.'}</p><p class="small-note">Comparação ilustrativa, sem equalização estatística entre as provas. Não constitui medida de proficiência Saeb ou nota oficial.</p></div><div class="panel"><h3>Eventos registrados</h3>${cycle.events.map(e=>`<div class="list-row"><span>${e.label}</span><small>${e.date}</small></div>`).join('')||'<p>Aguardando atividades.</p>'}</div>`}
function cycleManager(){return `${intro('Avaliação e recomposição da rede','Acompanhamento pedagógico de avaliações, intervenções e resultados.')} ${scoreCards()}<div class="panel"><h3>Ciclo ilustrativo — Escola Municipal Horizonte · 5º ano A</h3>${cycleTimeline()}</div><div class="cycle-grid"><div class="panel"><h3>Diagnósticos</h3><p>Visão por etapa, turma e área do conhecimento.</p><button class="btn secondary sm" onclick="go('dashboard','evaluations')">Matrizes e avaliações →</button></div><div class="panel"><h3>Intervenções</h3><p>${cycle.reinforcement?'Uma atribuição de reforço demonstrativa registrada para a turma.':'Nenhuma intervenção registrada no fluxo demonstrativo.'}</p><button class="btn secondary sm" onclick="go('dashboard','cycle-report')">Ver evolução →</button></div><div class="panel"><h3>Resultados</h3><p>Comparação entre diagnóstico e reavaliação, sem equivalência com Saeb ou Ideb.</p><button class="btn secondary sm" onclick="go('dashboard','cycle-report')">Acompanhar evolução →</button></div></div><div class="panel"><h3>Visão consolidada por escola (dados ilustrativos independentes)</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Unidade</th><th>Etapa</th><th>Prioridade pedagógica</th><th>Ação</th></tr></thead><tbody><tr><td>Escola Horizonte</td><td>5º ano</td><td>Frações</td><td>Trilha de reforço</td></tr><tr><td>Escola Jardim Azul</td><td>2º ano</td><td>Alfabetização</td><td>Leitura orientada</td></tr><tr><td>Escola Primavera</td><td>9º ano</td><td>Leitura de gráficos</td><td>Oficina de interpretação</td></tr></tbody></table></div><p class="small-note">Tabela inteiramente fictícia, não derivada do aluno demonstrativo.</p></div>`}
function resetCycle(){if(!confirm('Reiniciar o ciclo demonstrativo? Os resultados locais serão apagados.'))return;cycle=defaultCycle();saveCycle();v2quiz={type:'diagnostic',pos:0,answers:{}};state.result=null;state.answers={};state.question=0;go('dashboard','cycle');toast('Demonstração reiniciada.')}
function evaluationPublic(){const etapas=[['Educação Infantil','Observação e registros formativos','Desenvolvimento integral e documentação pedagógica; sem prova padronizada individual.'],['2º ano do Fundamental','Alfabetização e Matemática','Avaliações diagnósticas de habilidades fundamentais e apoio à alfabetização.'],['5º ano do Fundamental','Saeb e diagnóstico por habilidade','Simulados e atividades de Língua Portuguesa e Matemática; matriz conforme edição.'],['6º a 8º ano','Avaliação contínua','Diagnósticos periódicos e preparação progressiva para a etapa final.'],['9º ano do Fundamental','Saeb — anos finais','Atividades orientadas às matrizes de referência aplicáveis.'],['Ensino Médio','Saeb e Enem','Expansão planejada: questões por área e simulados.'],['Educação de Jovens e Adultos','Encceja','Expansão planejada: percursos para certificação.']];return `${pageHeader('Avaliações e aprendizagem','Avaliar para apoiar cada estudante','Diagnósticos, recursos pedagógicos e reavaliação, conectados à prática docente.')}<section class="section"><div class="container"><div class="section-head"><div class="eyebrow">Ciclo completo</div><h2>Do diagnóstico à recomposição</h2><p>O professor identifica necessidades, atribui atividades e acompanha o progresso do estudante. O gestor observa indicadores consolidados.</p></div>${flow()}<div class="section-head" style="margin-top:50px"><h2>Referências por etapa escolar</h2><p>As funcionalidades foram organizadas a partir das avaliações descritas no material de referência do projeto. A aplicação oficial e as matrizes variam conforme o programa e a edição.</p></div><div class="feature-grid">${etapas.map(([t,n,d])=>`<article class="card"><span class="label">${t}</span><h3 style="margin-top:14px">${n}</h3><p>${d}</p></article>`).join('')}</div><div class="panel" style="margin-top:25px"><h3>Indicadores e limites</h3><p>O Ideb é indicador oficial, não um teste aplicado pelo EducaConecta. BNCC, descritores e matrizes do Saeb exigem alinhamento pedagógico específico. Questões deste protótipo são autorais e ilustrativas, não oficiais do Inep.</p><button class="btn" onclick="selectRole('student');go('dashboard','cycle')">Experimentar ciclo completo →</button></div></div></section>`}
/* Integrações da V2 nos menus e nas páginas já existentes */
menus.student.splice(3,0,['cycle','🧭','Avaliação e recomposição']);
menus.teacher.splice(3,0,['cycle','🧭','Avaliação e recomposição']);
menus.manager.splice(4,0,['cycle','🧭','Avaliação e recomposição']);
const headerV1=header;header=function(){return headerV1().replace("[['home','Início'],['about','Sobre'],['resources','Recursos BNCC'],['courses','Formação'],['news','Notícias'],['help','Ajuda']]", "[['home','Início'],['about','Sobre'],['resources','Recursos BNCC'],['courses','Formação'],['news','Notícias'],['help','Ajuda']]")};
const oldStudent=studentPanel;studentPanel=function(){if(state.tab==='cycle')return cycleStudent();if(state.tab==='cycle-quiz')return cycleQuiz();if(state.tab==='cycle-results')return resultPanel();if(state.tab==='cycle-report')return cycleReport();return oldStudent()};
const oldTeacher=teacherPanel;teacherPanel=function(){if(state.tab==='cycle')return cycleTeacher();if(state.tab==='cycle-report')return cycleReport();return oldTeacher()};
const oldManager=managerPanel;managerPanel=function(){if(state.tab==='cycle')return cycleManager();if(state.tab==='cycle-report')return cycleReport();return oldManager()};
const oldHome=home;home=function(){return oldHome().replace('<div class="container role-cards">','<div class="container role-cards">').replace('Ver painel de diagnóstico →','Experimentar o ciclo completo →').replace("go('dashboard','diagnostics')\"", "go('dashboard','cycle')\"")};
const renderOld=render;render=function(){if(state.page==='evaluation-public'){A.innerHTML=header()+evaluationPublic()+footer();document.title='EducaConecta | Avaliações e aprendizagem';return}renderOld();let nav=document.getElementById('nav');if(nav){let a=document.createElement('a');a.href='#evaluation-public';a.textContent='Saeb · Enem · Encceja';a.className=state.page==='evaluation-public'?'active':'';a.onclick=function(e){e.preventDefault();go('evaluation-public');nav.classList.remove('open')};let ref=[...nav.querySelectorAll('a')].find(x=>x.textContent==='Formação');nav.insertBefore(a,ref||null)}if(state.page==='dashboard'){let m=document.querySelector('.dash-main');if(m&&state.tab==='cycle'){let b=document.createElement('div');b.className='cycle-actions';b.innerHTML=`<button class="btn ghost sm" onclick="resetCycle()">↻ Reiniciar demonstração</button><span class="small-note">Os passos deste ciclo ficam registrados neste navegador.</span>`;m.appendChild(b)}}};
const goOld=go;go=function(page,tab){goOld(page,tab)};

/* V3 — Acesso educacional por avaliação externa; questões 100% demonstrativas */
const examData={
 saeb:{name:'Saeb',subtitle:'Apoio à aprendizagem no Ensino Fundamental',icon:'📘',accent:'blue',desc:'Diagnósticos por etapa, exercícios de Língua Portuguesa e Matemática, e orientações de recomposição para a turma.',grades:['2º ano · alfabetização','5º ano · Língua Portuguesa e Matemática','9º ano · habilidades dos anos finais'],items:[['2º ano','Alfabetização','Qual palavra começa com a mesma sílaba de BOLA?',['Boneca','Casa','Pato','Mesa'],0],['5º ano','Matemática','Uma pizza foi dividida em 8 partes e 3 foram consumidas. Que fração foi consumida?',['3/8','8/3','5/8','3/5'],0],['9º ano','Matemática','Se 3 cadernos custam R$ 24, quanto custam 5 cadernos de mesmo preço?',['R$ 30','R$ 36','R$ 40','R$ 48'],2]]},
 enem:{name:'Enem',subtitle:'Preparação para o Ensino Médio',icon:'🎓',accent:'purple',desc:'Questões demonstrativas por área do conhecimento, prática de resolução e revisão de competências do Ensino Médio.',grades:['Linguagens','Matemática','Ciências Humanas','Ciências da Natureza'],items:[['Linguagens','Interpretação','Um texto defende uma opinião utilizando exemplos e argumentos. Sua finalidade predominante é:',['Narrar fatos','Argumentar','Descrever um ambiente','Dar instruções'],1],['Matemática','Porcentagem','Um produto de R$ 200 recebeu 15% de desconto. Qual é o preço final?',['R$ 170','R$ 175','R$ 180','R$ 185'],0],['Ciências da Natureza','Ecologia','Em uma cadeia alimentar, os produtores são geralmente:',['Fungos','Animais carnívoros','Plantas e algas','Bactérias decompositoras'],2]]},
 encceja:{name:'Encceja',subtitle:'Percursos para jovens e adultos',icon:'📗',accent:'green',desc:'Trilhas e exercícios demonstrativos voltados à revisão de conhecimentos para certificação do Ensino Fundamental e do Médio.',grades:['Ensino Fundamental','Ensino Médio','Revisão de conteúdos','Atividades práticas'],items:[['Ensino Fundamental','Matemática cotidiana','Uma compra de R$ 35 foi paga com R$ 50. Qual é o troco?',['R$ 10','R$ 15','R$ 20','R$ 25'],1],['Ensino Fundamental','Leitura','Em um aviso escrito “Vacinação amanhã, das 8h às 12h”, o objetivo principal é:',['Informar um serviço','Narrar uma história','Anunciar um produto','Apresentar uma opinião'],0],['Ensino Médio','Matemática','Um aparelho de 100 W ligado por 2 horas consome quantos Wh?',['50 Wh','100 Wh','200 Wh','500 Wh'],2]]}
};
let examKey='saeb', examIndex=0,examAnswers={};
function examCards(){return `<div class="exam-cards">${Object.entries(examData).map(([k,x])=>`<article class="exam-card ${x.accent}"><div class="exam-icon">${x.icon}</div><div class="eyebrow">PREPARAÇÃO E APRENDIZAGEM</div><h3>${x.name}</h3><p>${x.subtitle}</p><p class="exam-desc">${x.desc}</p><button class="btn sm" onclick="openExam('${k}')">Conhecer ${x.name} →</button></article>`).join('')}</div>`}
function examLanding(){return `${pageHeader('Avaliações nacionais','Prepare-se, pratique e evolua','Escolha uma avaliação para conhecer percursos de estudo, realizar exercícios demonstrativos e descobrir formas de acompanhar o aprendizado.')}<section class="section"><div class="container">${examCards()}<div class="section-head" style="margin-top:55px"><h2>Avaliar para aprender melhor</h2><p>Diagnóstico, análise dos resultados, reforço direcionado e nova avaliação fazem parte de um único percurso pedagógico.</p></div>${flow()}<div class="panel" style="margin-top:25px"><h3>Diagnóstico do 5º ano: demonstração integrada</h3><p>Faça a avaliação como estudante, acesse o painel de pontos de atenção como professor e acompanhe a evolução como gestor.</p><button class="btn" onclick="selectRole('student');go('dashboard','cycle')">Experimentar ciclo completo →</button></div><p class="small-note">Atividades de demonstração, não provas oficiais do Inep. A abrangência de cada avaliação depende de suas matrizes e edições.</p></div></section>`}
function openExam(k){examKey=k;examIndex=0;examAnswers={};go('exam-detail');}
function examDetail(){let x=examData[examKey];if(!x){examKey='saeb';x=examData.saeb}return `${pageHeader('Preparação para avaliações',x.name,x.subtitle)}<section class="section"><div class="container"><button class="btn ghost sm" onclick="go('evaluation-public')">← Todas as avaliações</button><div class="exam-detail-grid"><div><h2>Estude com foco nas habilidades</h2><p>${x.desc}</p><h3>Etapas e áreas de estudo</h3><div class="exam-topics">${x.grades.map(y=>`<span class="label">${y}</span>`).join('')}</div><div class="panel" style="margin-top:25px"><h3>Como funciona</h3><p>1. Selecione uma área de estudo e pratique. 2. Receba devolutiva das respostas. 3. Revise conteúdos. 4. Acompanhe o desenvolvimento.</p><button class="btn" onclick="go('exam-quiz')">Experimentar questões →</button></div></div><div class="panel"><div class="exam-icon">${x.icon}</div><h3>Prática demonstrativa</h3><p>3 questões autorais com correção automática e devolutiva por área.</p><p>O percurso completo de diagnóstico, intervenção e reavaliação já está disponível para Matemática do 5º ano.</p>${examKey==='saeb'?`<button class="btn secondary" onclick="selectRole('student');go('dashboard','cycle')">Abrir diagnóstico do 5º ano →</button>`:''}</div></div><p class="small-note">Simulações educacionais não oficiais; este protótipo não reproduz provas, pontuações ou níveis de proficiência do Inep.</p></div></section>`}
function examQuiz(){let x=examData[examKey];let q=x.items[examIndex];return `${pageHeader('Atividade demonstrativa',`Exercícios ${x.name}`,'Responda às questões e consulte a devolutiva ao final.')}<section class="section"><div class="container" style="max-width:850px"><button class="btn ghost sm" onclick="go('exam-detail')">← Voltar para ${x.name}</button><div class="panel" style="margin-top:20px"><span class="label">${q[0]} · ${q[1]}</span><p class="muted">Questão ${examIndex+1} de ${x.items.length}</p><div class="progress-track"><div class="progress-fill" style="width:${(examIndex+1)/x.items.length*100}%"></div></div><h2 style="margin:24px 0">${q[2]}</h2><div class="answers">${q[3].map((a,i)=>`<button class="answer ${examAnswers[examIndex]===i?'chosen':''}" onclick="examAnswers[${examIndex}]=${i};render()">${'ABCD'[i]}. ${a}</button>`).join('')}</div><div class="exam-actions"><button class="btn secondary" ${examIndex===0?'disabled':''} onclick="examIndex--;render()">Anterior</button><button class="btn" ${examAnswers[examIndex]===undefined?'disabled':''} onclick="if(examIndex===${x.items.length-1}){go('exam-result')}else{examIndex++;render()}">${examIndex===x.items.length-1?'Ver resultado':'Próxima questão →'}</button></div></div></div></section>`}
function examResult(){let x=examData[examKey],hit=x.items.filter((q,i)=>examAnswers[i]===q[4]).length;return `${pageHeader('Devolutiva',`Resultado · ${x.name}`,'Exercício demonstrativo concluído.')}<section class="section"><div class="container" style="max-width:850px"><div class="stats">${stat(hit+' / '+x.items.length,'Acertos')}${stat(Math.round(hit/x.items.length*100)+'%','Aproveitamento')}${stat(x.items.length,'Questões')}${stat(x.items.length-hit,'Pontos para revisar')}</div><div class="panel"><h3>Revisão por área</h3>${x.items.map((q,i)=>`<div class="list-row"><div><strong>${q[0]} · ${q[1]}</strong><small>${q[2]}</small></div><span class="label ${examAnswers[i]===q[4]?'green':'gold'}">${examAnswers[i]===q[4]?'Correto':'Revisar'}</span></div>`).join('')}<p class="small-note">Este resultado não equivale a uma nota oficial ou estimativa de proficiência.</p><button class="btn" onclick="examIndex=0;examAnswers={};go('exam-quiz')">Refazer exercícios</button> <button class="btn secondary" onclick="go('evaluation-public')">Outras avaliações</button></div></div></section>`}
const v3PreviousRender=render;render=function(){if(['exam-detail','exam-quiz','exam-result'].includes(state.page)){A.innerHTML=header()+({ 'exam-detail':examDetail,'exam-quiz':examQuiz,'exam-result':examResult}[state.page]())+footer();document.title='EducaConecta | '+examData[examKey].name;return}if(state.page==='evaluation-public'){A.innerHTML=header()+examLanding()+footer();document.title='EducaConecta | Saeb, Enem e Encceja';return}v3PreviousRender();if(state.page==='home'){let target=document.querySelector('.role-cards');if(target){let section=document.createElement('section');section.className='section';section.innerHTML=`<div class="container"><div class="section-head"><div class="eyebrow">AVALIAÇÕES E APRENDIZAGEM</div><h2>Prepare-se para Saeb, Enem e Encceja</h2><p>Estude por etapa de ensino, faça atividades e acompanhe seus pontos de atenção.</p></div>${examCards()}</div>`;target.after(section)}}};
const v3OldGo=go;go=function(page,tab){v3OldGo(page,tab)};
(function init(){const hash=location.hash.slice(1).split('/');if(['home','about','resources','courses','news','help','login','dashboard','evaluation-public','exam-detail','exam-quiz','exam-result'].includes(hash[0])){state.page=hash[0];if(hash[1])state.tab=hash[1]}render()})();
